import {useEffect,useState} from 'react';
import {CalendarDays,RefreshCw} from 'lucide-react';
import {listPracticeCalendar} from '../../lib/practiceOperationsApi';

const VIEWS=['AGENDA','DAY','WEEK','MONTH'];
export function ExternalCalendarWorkspace(){const [view,setView]=useState('AGENDA');const [page,setPage]=useState({items:[]});const [loading,setLoading]=useState(true);const [error,setError]=useState('');async function load(){setLoading(true);setError('');try{setPage(await listPracticeCalendar({view}))}catch(reason){setError(reason.message||'Calendar could not load.')}finally{setLoading(false)}}useEffect(()=>{void load()},[view]);return <div className="space-y-6 pb-24 lg:pb-8"><header><p className="text-xs font-bold uppercase tracking-[.16em] text-blue-700">Practice</p><h2 className="mt-2 text-3xl font-bold tracking-tight">Calendar</h2><p className="mt-2 text-sm text-slate-600">Consultations, follow-ups and task due dates in one tenant-scoped view.</p></header><nav aria-label="Calendar view" className="flex gap-2 overflow-x-auto">{VIEWS.map(item=><button key={item} onClick={()=>setView(item)} aria-current={view===item?'page':undefined} className={`min-h-11 shrink-0 rounded-full px-4 text-sm font-bold ${view===item?'bg-slate-950 text-white':'border bg-white text-slate-700'}`}>{item[0]+item.slice(1).toLowerCase()}</button>)}</nav>{error&&<div role="alert" className="rounded-2xl border border-red-200 bg-red-50 p-4 text-sm text-red-800">{error}<button onClick={load} className="ml-3 font-bold"><RefreshCw className="inline" size={15}/> Retry</button></div>}{loading?<div role="status" className="min-h-40 animate-pulse rounded-3xl bg-white p-6">Loading calendar…</div>:page.items.length?<div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{page.items.map(item=><article key={`${item.source_type}-${item.id}`} className="rounded-2xl border border-slate-200 bg-white p-5"><span className="text-xs font-bold uppercase tracking-wider text-blue-700">{item.source_type.replaceAll('_',' ')}</span><h3 className="mt-2 font-bold">{item.title}</h3><p className="mt-2 text-sm text-slate-500">{new Date(item.starts_at).toLocaleString()}</p><span className="mt-4 inline-flex rounded-full bg-slate-100 px-2.5 py-1 text-xs font-semibold">{item.status.replaceAll('_',' ')}</span></article>)}</div>:<div className="rounded-3xl border border-dashed border-slate-300 bg-white px-6 py-16 text-center"><CalendarDays className="mx-auto text-blue-700"/><h3 className="mt-4 text-lg font-bold">No scheduled work in this view</h3><p className="mt-2 text-sm text-slate-500">Scheduled consultations, follow-ups and task due dates will appear automatically.</p></div>}</div>}
